"""Hive auto-rig: Maya scene builder (generated by hive-rig).

Builds every character of a hive-rig scene in one Maya scene, each from its own
builder script next to this one (`<character>_maya.py`) inside a namespace
named after it (`hero:pelvis`), so characters with the same joint names live
side by side, and stands it where the scene places it. A prop held across
characters gets a `held` attribute on the prop's control (0: it stays on its
own socket, 1: it follows the holder's joint) weighting a parent constraint on
a `<control>_held` group above it.

Run in Maya 2022+ (Script Editor > Python tab > Load Script > Execute), or
`mayapy <this file> --save scene.ma` to build headless. A character's Hive Rig
window works in its namespace: `use("hero")` makes it current and opens it.
"""

import json
import os
import sys

import maya.cmds as cmds

if not hasattr(cmds, "about"):  # running under mayapy without a UI
    import maya.standalone

    maya.standalone.initialize(name="python")

SCENE = json.loads(r"""__HIVE_SCENE_JSON__""")
HERE = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
SCALE = 100.0  # hive data is in metres; Maya's default unit is centimetres
CHARACTERS = {}  # name -> the character script's globals


def in_namespace(name):
    """Make `name` the current namespace, with names read relative to it."""
    if not cmds.namespace(exists=":" + name):
        cmds.namespace(add=name, parent=":")
    cmds.namespace(set=":" + name)
    cmds.namespace(relativeNames=True)


def back_to_root():
    cmds.namespace(relativeNames=False)
    cmds.namespace(set=":")


def load_character(c):
    """Run a character's builder script as a module and return its globals."""
    path = os.path.join(HERE, c["script"])
    if not os.path.isfile(path):
        raise RuntimeError("hive-rig: %s is missing; export %s from the scene again" % (path, c["name"]))
    ns = {"__name__": "hive_scene_" + c["name"], "__file__": path}
    with open(path) as f:
        exec(compile(f.read(), path, "exec"), ns)
    return ns


def build_character(c):
    """Build one character in its namespace (or find it built) and place it."""
    ns = load_character(c)
    CHARACTERS[c["name"]] = ns
    in_namespace(c["name"])
    try:
        top = ns["TOP"]
        if not (cmds.objExists(top) and cmds.attributeQuery("hiveGuides", node=top, exists=True)):
            ns["build"](ns["RIG_DATA"])
            ns["add_studio_pose"](ns["RIG_DATA"])
        cmds.xform(top, worldSpace=True, translation=[v * SCALE for v in c["offset"]])
        if not cmds.attributeQuery("hiveScene", node=top, exists=True):
            cmds.addAttr(top, longName="hiveScene", dataType="string")
        cmds.setAttr(top + ".hiveScene", SCENE["name"], type="string")
    finally:
        back_to_root()
    return c["name"] + ":" + ns["TOP"]


def hold(h):
    """The prop's control follows the holder's joint by its `held` attribute."""
    ctrl = "%s:%s" % (h["prop_character"], h["prop_control"])
    joint = "%s:%s" % (h["holder_character"], h["holder_bone"])
    parent = cmds.listRelatives(ctrl, parent=True)[0]
    group = ctrl + "_held"
    if not cmds.objExists(group):
        group = cmds.group(empty=True, name=group, parent=parent)
        cmds.parent(ctrl, group, relative=True)
    con = cmds.parentConstraint(joint, group, maintainOffset=True, name=h["prop_control"] + "_held_con")[0]
    # With no weight it sits at rest: on its own socket.
    cmds.setAttr(con + ".enableRestPosition", 1)
    if not cmds.attributeQuery("held", node=ctrl, exists=True):
        cmds.addAttr(ctrl, longName="held", attributeType="double", minValue=0.0, maxValue=1.0,
                     defaultValue=float(h["held"]), keyable=True)
    cmds.setAttr(ctrl + ".held", float(h["held"]))
    alias = cmds.parentConstraint(con, query=True, weightAliasList=True)[0]
    cmds.connectAttr(ctrl + ".held", con + "." + alias, force=True)
    return con


def use(name):
    """Work on one character: its namespace current, its Hive Rig window open."""
    in_namespace(name)
    if not cmds.about(batch=True):
        CHARACTERS[name]["show_window"]()


def build():
    tops = [build_character(c) for c in SCENE["characters"]]
    holds = [hold(h) for h in SCENE["holds"]]
    return tops, holds


def main():
    tops, holds = build()
    print("hive-rig: scene %s with %d characters (%s) and %d held props"
          % (SCENE["name"], len(tops), ", ".join(c["name"] for c in SCENE["characters"]), len(holds)))
    if "--save" in sys.argv:
        path = sys.argv[sys.argv.index("--save") + 1]
        cmds.file(rename=path)
        cmds.file(save=True, type="mayaAscii" if path.endswith(".ma") else "mayaBinary")
    elif not cmds.about(batch=True) and SCENE["characters"]:
        use(SCENE["characters"][-1]["name"])


if __name__ == "__main__":
    main()
